#!/usr/bin/env python3
"""Run in Codespace: python3 install_quant.py"""
import base64, json, os, shutil

PAYLOAD = """"""

def main():
    data = json.loads(base64.b64decode(PAYLOAD))
    for d in ["src", "public", "streamlit_app", "patches", "scripts", "node_modules", ".next", "__pycache__"]:
        shutil.rmtree(d, ignore_errors=True)
    for f in ["AGENTS.md", "CLAUDE.md", "components.json", "eslint.config.mjs", "next.config.ts",
              "package.json", "package-lock.json", "postcss.config.mjs", "tsconfig.json", ".env.example"]:
        try: os.remove(f)
        except FileNotFoundError: pass
    for path, content in data.items():
        os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
        with open(path, "w", encoding="utf-8") as fh:
            fh.write(content)
        print(f"  wrote {path}")
    print("\nDone. Run:")
    print("  pip install -r requirements.txt")
    print("  git add -A && git commit -m 'Replace TradePath with Quant Stock Analytics app' && git push origin main")

if __name__ == "__main__":
    main()
    